const params=new URLSearchParams(location.search),codeFromUrl=params.get('room')??'';
let session:SessionInfo|null=null,snapshot:RoomSnapshot|null=null,socket:WebSocket|null=null,connected=false,epoch=0,renderer:BattleRenderer|null=null;
let screenKey='',panelKey='',lobbyKey='',quizOpen=false,quizFeedback:AnswerFeedback|null=null,selectedOption='',pendingUI=false,showDiagnostics=false,sound=false,lowPerformance=localStorage.getItem('classclash:low-performance')==='true';
let lastMatch:string|null=null,lastPlayerState='',bankDraft='',bankResult='',drawResult:OwnedHero|null=null,toastTimer=0,reconnectTimer=0,entryTab=codeFromUrl?'join':'create';
let latestEventSeq=0,snapshotRecovery=false,awaitingRecoverySnapshot=false;const pending=new Map<string,{command:ClientCommand;resolve:(reply:CommandReply)=>void;reject:(error:Error)=>void;sentAt:number}>();
