const status=()=>`<div class="connection ${connected?'':'lost'}"><span class="dot ${connected?'':'offline'}"></span>${connected?'서버 연결됨':'재연결 중 · 진행은 서버에 보관됩니다'}</div>`;
function toast(message:string){const el=document.querySelector('#toast')!;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>el.classList.remove('show'),4200);}
const stableMarkup=new WeakMap<Element,string>();
function setStableMarkup(selector:string,html:string){const el=document.querySelector(selector)!;if(stableMarkup.get(el)===html)return;el.innerHTML=html;stableMarkup.set(el,html);}
function errorText(error:unknown){return error instanceof Error?error.message:String(error);}
function saveSession(s:SessionInfo){session=s;sessionStorage.setItem('classclash:active',JSON.stringify(s));localStorage.setItem(`classclash:${s.role}:${s.roomCode}`,JSON.stringify(s));localStorage.setItem('classclash:last',JSON.stringify(s));}
function loadSession(){try{const saved=sessionStorage.getItem('classclash:active');if(saved){const s=JSON.parse(saved) as SessionInfo;if(!codeFromUrl||s.roomCode===codeFromUrl){session=s;return;}}}catch{/* invalid local data does not grant access */}}
async function post<T>(url:string,data:unknown):Promise<T>{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const body=await response.json();if(!response.ok)throw new Error(body.message??body.error??'요청을 처리하지 못했습니다. 다시 시도해 주세요.');return body;}

function connect(){if(!session)return;clearTimeout(reconnectTimer);socket?.close();const ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);socket=ws;ws.addEventListener('open',()=>{if(socket!==ws)return;ws.send(JSON.stringify({type:'HELLO',roomCode:session!.roomCode,token:session!.token,lastEventSeq:latestEventSeq}));});
 ws.addEventListener('message',event=>{if(socket!==ws)return;let message;try{message=JSON.parse(String(event.data));}catch{return;}if(message.type==='WELCOME'){awaitingRecoverySnapshot=true;epoch=message.connectionEpoch;connected=true;for(const p of pending.values()){p.command.connectionEpoch=epoch;ws.send(JSON.stringify({type:'COMMAND',command:p.command}));}renderConnection();}else if(message.type==='SNAPSHOT'){const next=message.snapshot as RoomSnapshot;if(!acceptSnapshot(snapshot,next,epoch))return;snapshotRecovery=awaitingRecoverySnapshot;awaitingRecoverySnapshot=false;if(lastMatch!==next.matchId){lastMatch=next.matchId;quizFeedback=null;selectedOption='';quizOpen=next.phase==='OPENING_QUIZ';drawResult=null;latestEventSeq=0;panelKey='';}if(snapshot?.phase==='OPENING_QUIZ'&&next.phase!=='OPENING_QUIZ'){quizOpen=false;quizFeedback=null;selectedOption='';panelKey='';}if(snapshot?.self?.quiz?.question?.id!==next.self?.quiz?.question?.id)selectedOption='';const prevState=lastPlayerState;snapshot=next;connected=true;const draftKey=quizDraftKey();if(!selectedOption&&draftKey){const draft=sessionStorage.getItem(draftKey);if(next.self?.quiz?.question?.options.some(o=>o.id===draft))selectedOption=draft!;}const player=currentPlayer();lastPlayerState=player?.state??'';if(player?.state==='DEAD_MAINTENANCE'&&prevState==='ACTIVE'){if(!quizOpen)panelKey='';toast('영웅이 쓰러졌습니다. 퀴즈를 이어 풀거나 정비에서 다시 출정하세요.');}if(next.battle)latestEventSeq=Math.max(latestEventSeq,next.battle.eventSeq);render();}else if(message.type==='ACK'){const item=pending.get(message.reply.commandId);if(item){pending.delete(message.reply.commandId);if(message.reply.status==='REJECTED')item.reject(new Error(message.reply.message??message.reply.errorCode??'요청이 거절되었습니다.'));else item.resolve(message.reply);}}else if(message.type==='ERROR'){toast(message.message??message.error??'연결을 확인해 주세요.');if(/AUTH|NOT_FOUND/.test(message.code??message.errorCode??'')){sessionStorage.removeItem('classclash:active');session=null;screenKey='';renderEntry();}}});
 ws.addEventListener('message',event=>{if(socket!==ws)return;try{const m=JSON.parse(String(event.data));if(m.type==='SNAPSHOT'&&m.snapshot.battle&&m.snapshot.connectionEpoch===epoch)ws.send(JSON.stringify({type:'EVENT_ACK',lastEventSeq:m.snapshot.battle.eventSeq}));if(m.type==='REPLACED'){socket=null;connected=false;toast(m.message??'다른 창에서 연결되었습니다. 이 창은 읽기 전용입니다.');renderConnection();}}catch{}});
 ws.addEventListener('close',()=>{if(socket!==ws)return;connected=false;renderConnection();if(session)reconnectTimer=window.setTimeout(connect,1500);});ws.addEventListener('error',()=>{if(socket!==ws)return;connected=false;renderConnection();});
}
function send(type:string,payload:Record<string,unknown>={}):Promise<CommandReply>{if(snapshot?.self&&currentPlayer()?.state==='DEAD_MAINTENANCE'&&['DRAW_HERO','LEVEL_UP','ENHANCE_HERO','SELECT_HERO_AND_LANE','DEPLOY_HERO'].includes(type))payload={...payload,deathId:snapshot.self.deathId};if(!snapshot||!session)return Promise.reject(new Error('서버에 다시 연결한 뒤 시도해 주세요.'));const command:ClientCommand={commandId:crypto.randomUUID(),matchId:snapshot.matchId,expectedPhaseRevision:snapshot.phaseRevision,connectionEpoch:epoch,type,payload};if(['DRAW_HERO','LEVEL_UP','ENHANCE_HERO','CLAIM_STARTER'].includes(type))command.ledgerRevision=snapshot.self?.ledgerRevision;
 return new Promise((resolve,reject)=>{pending.set(command.commandId,{command,resolve,reject,sentAt:performance.now()});if(connected&&socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'COMMAND',command}));else toast('연결을 복구하고 있습니다. 선택한 요청은 같은 번호로 확인합니다.');scheduleRetry(command.commandId,0);});}
async function action(type:string,payload:Record<string,unknown>={},success?:string){if(pendingUI)return;pendingUI=true;try{const reply=await send(type,payload);if(success)toast(success);return reply;}catch(error){toast(errorText(error));}finally{pendingUI=false;}}
function scheduleRetry(id:string,attempt:number){window.setTimeout(()=>{const item=pending.get(id);if(!item)return;if(attempt>=3){pending.delete(id);item.reject(new Error('서버의 확정을 확인하지 못했습니다. 연결 후 현재 상태를 확인해 주세요.'));return;}if(connected&&socket?.readyState===WebSocket.OPEN){item.command.connectionEpoch=epoch;socket.send(JSON.stringify({type:'COMMAND',command:item.command}));socket.send(JSON.stringify({type:'RESYNC'}));toast('응답을 기다리고 있습니다. 같은 요청 번호로 안전하게 확인합니다.');}scheduleRetry(id,attempt+1);},15000);}
function renderConnection(){ updateTestBadge();document.querySelectorAll('.connection').forEach(el=>{el.outerHTML=status();});document.body.dataset.connected=String(connected);}
function destroyRenderer(){renderer?.destroy();renderer=null;}
