 document.querySelector('#lobby-footer')!.innerHTML=isHost()?`<div class="lobby-footer"><div><h3>모두 모였나요?</h3><p style="margin-top:5px">${s.players.some(p=>p.team==='A')&&s.players.some(p=>p.team==='B')?'시작하면 명단이 잠기고, 각자 20문제를 풉니다.':'청팀과 홍팀에 최소 1명씩 참가해야 시작할 수 있어요.'}</p></div><button class="primary" data-action="start-opening" ${s.players.some(p=>p.team==='A')&&s.players.some(p=>p.team==='B')?'':'disabled'}>시작 퀴즈 시작 →</button></div>`:`<div class="lobby-footer"><div><h3>참가가 완료되었습니다.</h3><p style="margin-top:5px">선생님이 시작하면 20문제를 풀고 첫 영웅을 고릅니다.</p></div><span class="pill gold">${currentPlayer()?.team==='A'?'청팀':'홍팀'} · 시작 대기</span></div>`;
 if(first){const invite=inviteUrl(s.roomCode);document.querySelector('#lobby-controls')!.innerHTML=`<div class="surface"><h3>우리 반 초대하기</h3><div class="row spread"><span class="room-code">${esc(s.roomCode)}</span><button class="small" data-action="copy-link">링크 복사</button></div><canvas id="invite-qr" class="qr" aria-label="학생 참가 링크 QR 코드"></canvas><p class="invite-link">${esc(invite)}</p></div>${isHost()?`<div class="surface"><h3>AI 학생 추가</h3><div class="form-grid"><label>인원<input id="bot-count" type="number" min="1" max="30" value="1"></label><label>학습 프로필<select id="bot-profile"><option value="STANDARD">표준</option><option value="BASIC">기초</option><option value="SKILLED">숙련</option></select></label><label>팀 배치<select id="bot-team"><option value="AUTO">자동 균형</option><option value="A">청팀</option><option value="B">홍팀</option></select></label><label>자원 사용<select id="bot-strategy"><option value="BALANCED">균형</option><option value="GROWTH">성장 우선</option><option value="COLLECTOR">수집 우선</option></select></label><label style="grid-column:1/-1">최초 선호 역할<select id="bot-role"><option value="AUTO">자동 · 팀 조합에 맞추기</option><option value="tank">탱커</option><option value="melee">근접</option><option value="ranged">원거리</option><option value="mage">마법</option><option value="support">지원</option></select></label></div><button data-action="add-bots" style="width:100%;margin:12px 0">+ AI 학생 추가</button><div class="fill-buttons"><button data-action="fill" data-count="10">10명 채우기</button><button data-action="fill" data-count="20">20명 채우기</button><button data-action="fill" data-count="30">30명 채우기</button></div><div class="row" style="margin-top:10px"><button class="quiet small" data-action="balance">팀 균형 맞추기</button><button class="quiet small" data-action="remove-all">AI 전부 제거</button></div></div><div class="surface"><details><summary><strong>AI 시험 재현 설정</strong></summary><label class="note" style="margin-top:10px">재현 시드 (선택)<input id="match-seed" maxlength="128" placeholder="비워 두면 매번 다른 경기"></label><p class="note">시드는 문항과 AI 판단에 적용합니다. 뽑기는 별도 서버 난수를 사용합니다. 전체 결정적 재현은 test:soak 시험으로 실행합니다.</p></details></div><div class="surface quiz-config"><details><summary><strong>퀴즈 설정</strong> <span id="bank-count" class="muted"></span></summary><p class="note">한 줄에 문제 | 정답 | 오답 | 오답 | 오답<br>20~1000문제. 빈 줄은 무시합니다.</p><textarea id="bank-input" placeholder="be in charge of | ~을 담당하다 | ~을 기다리다 | ~을 포기하다 | ~에 참여하다">${esc(bankDraft)}</textarea><button data-action="save-bank" class="small">문제 검토 및 저장</button><p id="bank-result" class="bank-result">${esc(bankResult)}</p></details></div>`:`<div class="surface stack"><h3>플레이 안내</h3><p class="note">정답 1개마다 1원을 얻어요.<br>영웅은 출정하면 스스로 싸워요.<br>전투 중에도 퀴즈를 풀 수 있어요.<br>쓰러지면 정비에서 성장·교체 후 직접 다시 출정하세요.</p></div>`}`;void QRCode.toCanvas(document.querySelector<HTMLCanvasElement>('#invite-qr')!,invite,{width:144,margin:1,color:{dark:'#182820',light:'#ffffff'}});}
